### **1순위: 지수 백오프 재시도 로직 추가** (VectorSearchFunction)
```javascript
// vectorSearch.js
async function invokeBedrockWithRetry(params, maxRetries = 5) {
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await bedrockClient.invokeModel(params).promise();
    } catch (error) {
      if (error.code === 'ThrottlingException' && attempt < maxRetries - 1) {
        const waitTime = Math.pow(2, attempt) * 1000 + Math.random() * 1000;
        console.log(`Throttled. Retrying in ${waitTime}ms...`);
        await new Promise(resolve => setTimeout(resolve, waitTime));
      } else {
        throw error;
      }
    }
  }
}
```

### **2순위: 요청 속도 제한 적용**
```javascript
// rateLimiter.js
class RateLimiter {
  constructor(maxRequestsPerSecond = 5) {
    this.maxRequests = maxRequestsPerSecond;
    this.queue = [];
    this.processing = false;
  }

  async execute(fn) {
    return new Promise((resolve, reject) => {
      this.queue.push({ fn, resolve, reject });
      this.process();
    });
  }

  async process() {
    if (this.processing || this.queue.length === 0) return;
    this.processing = true;

    while (this.queue.length > 0) {
      const { fn, resolve, reject } = this.queue.shift();
      try {
        resolve(await fn());
      } catch (error) {
        reject(error);
      }
      await new Promise(r => setTimeout(r, 1000 / this.maxRequests));
    }
    this.processing = false;
  }
}
```

### **3순위: 배치 설명 생성 최적화**
```javascript
// 동시 요청 제한
